# =============================================================================
# 14_figure1_design.R  -  Figure 1, study design. Sample numbers and key counts are read from result files.
# =============================================================================
source("R/00_config.R")
suppressMessages({ library(ggplot2) })
FIG <- "figures"; rp <- function(step, f) file.path(DIR_RES, step, f)
m   <- read_mat(file.path(DIR_PRO, "merged_log2FPKM.csv")); g131 <- read_mat(file.path(DIR_PRO, "GSE131193_log2counts.csv"))
deg <- read.csv(rp("03_combat_limma", "TableS6_significant_DEGs.csv"), row.names = 1)
m23 <- read.csv(file.path(DIR_PRO, "GSE23163_sample_annotation.csv")); n23 <- sum(m23$group %in% c("Sham", "IR24h"))
kg <- read.csv(rp("04_enrichment_ppi", "KEGG.csv")); pn <- read.csv(rp("04_enrichment_ppi", "PPI_nodes_score700.csv"))
sf <- read.csv(rp("05_wgcna", "soft_threshold.csv")); pw <- sf$Power[which(sf$signedR2 >= 0.85)[1]]
mt <- read.csv(rp("05_wgcna", "module_trait_primary_sorted.csv"))
ct <- read.csv(rp("06_ssgsea_sting", "ssGSEA_group_tests.csv")); nct <- sum(ct$FDR_wilcox[ct$comparison == "primary_ipsi_tMCAO_vs_ipsi_sham"] < 0.05)
en <- read.csv(rp("08_elastic_net", "elastic_net_summary.csv"))
box <- function(x, y, w, h, label, fill) list(geom_rect(aes(xmin = x - w / 2, xmax = x + w / 2, ymin = y - h / 2, ymax = y + h / 2), fill = fill, colour = "grey30", linewidth = 0.3),
                                         annotate("text", x = x, y = y, label = label, size = 2.15, lineheight = 0.95))
arr <- function(x, y, xend, yend) annotate("segment", x = x, y = y, xend = xend, yend = yend, arrow = arrow(length = unit(1.4, "mm"), type = "closed"), linewidth = 0.3, colour = "grey30")
C_DATA <- "#DDEBF7"; C_PROC <- "#FFF2CC"; C_AN <- "#E2EFDA"; C_SUP <- "#F4E1F0"
p <- ggplot() + coord_cartesian(xlim = c(0, 10.05), ylim = c(-0.35, 9.9), expand = FALSE) + theme_void() +
  annotate("text", x = 0.15, y = 9.75, label = "Public GEO datasets", hjust = 0, fontface = "bold", size = 2.6) +
  box(1.6, 8.8, 3.0, 1.0, sprintf("Merged cohort\nGSE131712 + GSE202659 (mouse cortex/hemisphere)\n6 Sham vs 6 tMCAO"), C_DATA) +
  box(5.0, 8.8, 3.2, 1.0, sprintf("GSE131193\nmouse brain microvessel fragments, n = %d\nSham/tMCAO x 1 d/7 d x ipsi/contralateral", ncol(g131)), C_DATA) +
  box(8.35, 8.8, 3.0, 1.0, sprintf("GSE23163 (mouse cortex, striatum)\nWT and Gpx1-/-, Sham vs I/R 24 h\nn = %d", n23), C_DATA) +
  box(8.35, 4.15, 3.0, 0.75, "GSE227317 (rat cortex)\n5 Sham vs 5 MCAO; 5-gene panel", C_DATA) +
  box(1.6, 7.25, 3.0, 0.85, sprintf("log2(FPKM + 1); %s common genes\nComBat (+ sensitivity analyses)", format(nrow(m), big.mark = ",")), C_PROC) +
  box(5.0, 7.25, 3.2, 0.85, "GEO columns assigned to GSM by title\nprimary contrast: ipsilateral tMCAO vs sham (6 vs 6)", C_PROC) +
  box(8.35, 7.25, 3.0, 0.85, "log2 GeneSpring ratios\ntwo hold-out tasks", C_PROC) +
  box(1.6, 5.6, 3.0, 1.15, sprintf("limma: %s DEGs\n(%d up / %d down; FDR < 0.05, |log2FC| > 0.585)\nGO / KEGG (%d pathways), STRING PPI\n(%d nodes); composite IFN/STING score",
                                   format(nrow(deg), big.mark = ","), sum(deg$logFC > 0), sum(deg$logFC < 0), nrow(kg), nrow(pn)), C_AN) +
  box(5.0, 5.6, 3.2, 1.15, sprintf("WGCNA (24 samples, power %d; %d modules)\nssGSEA, 28 immune cell types\n(Charoentong 2017; %d with FDR < 0.05)\nIFN/STING score vs immune signatures",
                                   pw, sum(mt$module != "MEgrey"), nct), C_AN) +
  box(8.35, 5.6, 3.0, 1.15, sprintf("Elastic Net (alpha 0.4, 10-fold CV)\ntrain cortex -> test striatum\ntrain WT -> test Gpx1-/-\n39-gene panel, full transcriptome, rebuilt panel"), C_AN) +
  box(3.3, 3.75, 4.6, 0.85, sprintf("Three-set intersection\nDEGs x WGCNA core genes x curated cGAS-STING genes"), C_AN) +
  box(8.35, 3.05, 3.0, 0.75, "Exploratory directional check\n(ROC, saturated CI)", C_SUP) +
  box(5.0, 1.75, 9.4, 1.15, paste("Transcriptomic output: concurrent upregulation of cGAS-STING-associated type I interferon signaling and MHC class I antigen-processing transcripts in CIRI;",
                                 "\nwithin-study model performance only (no external validation of the Elastic Net models).",
                                 "\nAll transcriptomic results are generated by the code repository (main numbers in results/number_ledger.csv)."), "grey95") +
  box(5.0, 0.3, 9.4, 0.95, paste("Experimental follow-up (this revision; Supplementary Figs. S4-S6)",
                                "\ntMCAO vs sham mouse brain, 24 h: RT-qPCR (7 genes); Western blot (STING, p-IRF3/IRF3, TAP1, TAP2, TAPBP)",
                                "\nBV2 microglia, OGD/R: time course (6, 12, 24, 48 h); vehicle vs H-151 at 24 h (also ISG15 and H2-K1)"), C_SUP) + arr(5.0, 1.17, 5.0, 0.79) +
  arr(1.6, 8.28, 1.6, 7.68) + arr(5.0, 8.28, 5.0, 7.68) + arr(8.35, 8.28, 8.35, 7.68) +
  arr(1.6, 6.82, 1.6, 6.18) + arr(5.0, 6.82, 5.0, 6.18) + arr(8.35, 6.82, 8.35, 6.18) +
  arr(2.4, 5.02, 2.6, 4.18) + arr(4.4, 5.02, 4.1, 4.18) +
  arr(3.3, 3.32, 3.3, 2.33) + arr(8.35, 3.77, 8.35, 3.43) + arr(8.35, 2.67, 8.35, 2.33) + annotate("segment", x = 9.85, y = 5.6, xend = 9.95, yend = 5.6, linewidth = 0.3, colour = "grey30") + annotate("segment", x = 9.95, y = 5.6, xend = 9.95, yend = 2.0, linewidth = 0.3, colour = "grey30") + arr(9.95, 2.0, 9.72, 2.0)
ggsave(file.path(FIG, "Figure_1.pdf"), p, width = 7.4, height = 5.9, units = "in", device = cairo_pdf, bg = "white")
ggsave(file.path(FIG, "Figure_1.tiff"), p, width = 7.4, height = 5.9, units = "in", dpi = 300, device = ragg::agg_tiff, compression = "lzw", bg = "white")
cat("saved Figure_1\n")
